import { MakeLogicType, afterMount, connect, kea, key, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { externalDataDestinationsDeliveryFailuresRetrieve } from 'products/warehouse_sources/frontend/generated/api'
import { DestinationDeliveryFailuresResponseApi } from 'products/warehouse_sources/frontend/generated/api.schemas'

export interface WarehouseDestinationDetailLogicProps {
    destinationId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface warehouseDestinationDetailLogicValues {
    currentTeamId: number | null // teamLogic
    failures: DestinationDeliveryFailuresResponseApi | null
    failuresError: string | null
    failuresLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface warehouseDestinationDetailLogicActions {
    loadFailures: () => any
    loadFailuresFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadFailuresSuccess: (
        failures: DestinationDeliveryFailuresResponseApi,
        payload?: any
    ) => {
        failures: DestinationDeliveryFailuresResponseApi
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface warehouseDestinationDetailLogicMeta {
    key: string
}

export type warehouseDestinationDetailLogicType = MakeLogicType<
    warehouseDestinationDetailLogicValues,
    warehouseDestinationDetailLogicActions,
    WarehouseDestinationDetailLogicProps,
    warehouseDestinationDetailLogicMeta
>

export const warehouseDestinationDetailLogic = kea<warehouseDestinationDetailLogicType>([
    path((key) => [
        'products',
        'data_warehouse',
        'frontend',
        'scenes',
        'WarehouseDestinationsScene',
        'warehouseDestinationDetailLogic',
        key,
    ]),
    props({} as WarehouseDestinationDetailLogicProps),
    key((props) => props.destinationId),
    connect(() => ({
        values: [teamLogic, ['currentTeamId']],
    })),
    loaders(({ props, values }) => ({
        failures: [
            // Null until loaded, so the page does not say "no failed deliveries" while the request runs.
            null as DestinationDeliveryFailuresResponseApi | null,
            {
                loadFailures: async () =>
                    await externalDataDestinationsDeliveryFailuresRetrieve(
                        String(values.currentTeamId),
                        props.destinationId
                    ),
            },
        ],
    })),
    reducers({
        failuresError: [
            null as string | null,
            {
                loadFailures: () => null,
                loadFailuresSuccess: () => null,
                loadFailuresFailure: (_, { error }) => error || 'Could not load the failed deliveries',
            },
        ],
    }),
    afterMount(({ actions }) => {
        actions.loadFailures()
    }),
])
